import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.CQdiwDJy.js";const u=JSON.parse('{"title":"Web 界面","description":"","frontmatter":{},"headers":[],"relativePath":"guide/webui.md","filePath":"guide/webui.md","lastUpdated":1788601681000}'),r={name:"guide/webui.md"};function i(s,e,l,c,n,h){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="web-界面" tabindex="-1">Web 界面 <a class="header-anchor" href="#web-界面" aria-label="Permalink to &quot;Web 界面&quot;">​</a></h1><p><code>tau web</code> 启动本地 Web 界面（默认 <code>127.0.0.1:8787</code>，永不暴露到网络）：浏览器里的计划卡片、思考面板与实时工具调用，背后是和 CLI 完全相同的引擎与安全门。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tau</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 启动并打开</span></span></code></pre></div><h2 id="两种模式" tabindex="-1">两种模式 <a class="header-anchor" href="#两种模式" aria-label="Permalink to &quot;两种模式&quot;">​</a></h2><ul><li><strong>plan 模式</strong>：意图 → 计划卡 → 审查徽章 → 你点 Run → 实时结果卡。高风险计划有卡片级显式确认框，deny 结论硬禁用 Run。</li><li><strong>agent 模式</strong>：多轮 goal 时间线。每轮显示计划、审查徽章、实时步骤输出；medium+ 轮次内联暂停，卡片上直接 Approve / Refuse，没有&quot;一次性预授权&quot;。</li></ul><h2 id="思考面板-v0-5-0" tabindex="-1">思考面板（v0.5.0） <a class="header-anchor" href="#思考面板-v0-5-0" aria-label="Permalink to &quot;思考面板（v0.5.0）&quot;">​</a></h2><p>规划进行时，provider 的思考实时流入可折叠面板（流式中钉住展开，完成后折叠为 &quot;Thought for Ns&quot;）；agent 模式下每一轮的规划思考与反思思考分别折叠进所属轮次。token 用量显示在卡片眉行。</p><h2 id="工具调用卡片与文件查看器-v0-5-0" tabindex="-1">工具调用卡片与文件查看器（v0.5.0） <a class="header-anchor" href="#工具调用卡片与文件查看器-v0-5-0" aria-label="Permalink to &quot;工具调用卡片与文件查看器（v0.5.0）&quot;">​</a></h2><p>agent 轮次里的工具步骤渲染为结构化卡片：工具名、风险徽章、可折叠的参数 JSON、实时输出。<code>file.read</code> 步骤则渲染成文件查看器——路径、语言徽章与 shiki 语法高亮正文，语言检测与工具层共享同一份逻辑。</p><h2 id="斜杠命令菜单-v0-6-0" tabindex="-1">斜杠命令菜单（v0.6.0） <a class="header-anchor" href="#斜杠命令菜单-v0-6-0" aria-label="Permalink to &quot;斜杠命令菜单（v0.6.0）&quot;">​</a></h2><p>在输入框敲下 <code>/</code>（或命令前缀，如 <code>/th</code>）会浮出命令菜单——<code>↑</code>/<code>↓</code> 移动、<code>Tab</code>/<code>Enter</code> 执行、<code>Esc</code> 关闭，鼠标悬停/点击同样可用。命令全部在客户端本地执行（<code>/new</code> 新线程、<code>/theme</code>、<code>/plan</code>、<code>/agent</code>、<code>/help</code>、<code>/settings</code>……），<strong>从不作为意图发给 AI</strong>；菜单读取与 TUI 面板同源的共享命令目录（<code>GET /api/commands</code>），展示与可执行永远一致。</p><h2 id="图片附件-v0-6-0" tabindex="-1">图片附件（v0.6.0） <a class="header-anchor" href="#图片附件-v0-6-0" aria-label="Permalink to &quot;图片附件（v0.6.0）&quot;">​</a></h2><p>回形针按钮、直接粘贴（Ctrl/⌘+V）与拖拽三种方式都汇入同一份经过校验的附件列表：PNG/JPEG/WebP/GIF，最多 4 张、单张 ≤4 MB；草稿以可移除的缩略 chip 呈现，只有图片没有文字时发送会用一条明确的默认意图。负载只随请求走一次——用户卡片保留名称/类型/大小（缩略图仅当前会话），对话流事件与 localStorage 中永远没有图片数据。有视觉能力的 provider（openai/anthropic/gemini/ollama）收到原生格式图片；纯文本 provider 会得到诚实的&quot;图片已被丢弃&quot;注记，而不是假装看见。服务端独立复验：媒体类型白名单、张数/大小上限、魔数嗅探（改名文本文件无法冒充图片）。</p><h2 id="沙箱预览与原生查看-v0-6-0" tabindex="-1">沙箱预览与原生查看（v0.6.0） <a class="header-anchor" href="#沙箱预览与原生查看-v0-6-0" aria-label="Permalink to &quot;沙箱预览与原生查看（v0.6.0）&quot;">​</a></h2><ul><li><strong>HTML 预览</strong>：结果/回答中的 ```html 代码块获得 preview 切换——内容在 <code>&lt;iframe sandbox=&quot;allow-scripts&quot;&gt;</code> 中打开（不加 allow-same-origin，不透明源无法触碰父页面、Cookie 与存储）；escape-first 的 markdown 管线一行未动，预览是独立沙箱通道。</li><li><strong>PDF / 图片原生查看</strong>：<code>file.read</code> 读取 PDF 或图片时不再把二进制当文本展示，而是经只读路由 <code>GET /api/file</code> 流入浏览器原生查看器（<code>&lt;embed&gt;</code> / <code>&lt;img&gt;</code>）。该路由工作区收容（复用写工具同一套遏制定义 + realpath 复检，符号链接穿越被封堵）、8 MB 上限、保守 mime 白名单（永不服务 html/js/svg 等可执行类型），403/404/413 语义明确。</li></ul><h2 id="本地会话" tabindex="-1">本地会话 <a class="header-anchor" href="#本地会话" aria-label="Permalink to &quot;本地会话&quot;">​</a></h2><p>对话线程持久化在浏览器 localStorage（键 <code>tau-webui-threads-v1</code>，上限 50 条），服务端 history 才是持久记录；卡片 schema 只增不改。设置面板展示<strong>脱敏后</strong>的有效配置（API key 永远是掩码）。</p><h2 id="模型与思考选择-v0-6-2" tabindex="-1">模型与思考选择（v0.6.2） <a class="header-anchor" href="#模型与思考选择-v0-6-2" aria-label="Permalink to &quot;模型与思考选择（v0.6.2）&quot;">​</a></h2><p>设置面板的 <strong>provider</strong> 区块升级为可选：模型行是目录驱动的下拉 （<code>GET /api/models</code>，含刷新按钮），经 <code>POST /api/config/model</code> 写入； <strong>thinking</strong> 行按服务端能力表渲染 mode（on/off）与 effort（low/medium/high） 分段控件——无旋钮的 provider 如实显示「无思考旋钮」提示，而非死控件。 两项写入与 CLI 同一条 <code>setConfigValue</code> 通道；gate 与风险策略依然不可从 浏览器修改。</p><h2 id="provider-配置-v0-6-1" tabindex="-1">Provider 配置（v0.6.1） <a class="header-anchor" href="#provider-配置-v0-6-1" aria-label="Permalink to &quot;Provider 配置（v0.6.1）&quot;">​</a></h2><p>设置面板的 <strong>provider setup</strong> 区块——凭据写入面：</p><ul><li><strong>模型链接查询</strong>：选择 provider 后端点自动带出（来自服务端下发的 provider 目录，与注册表奇偶校验锁定一致），无需手输 URL；高级折叠项可自定义端点（OpenAI 系写 <code>providers.&lt;name&gt;.baseUrl</code>，Ollama 写 <code>host</code>）。</li><li><strong>只粘贴 key</strong>：从控制台链接取 key（每条目录附 &quot;get a … key ↗&quot;），粘贴即存；保存走 <code>POST /api/config/provider</code>——与 CLI <code>tau provider set-key</code> 同一条 <code>setConfigValue</code> 通道（0600 配置文件），保存后自动刷新模型目录，并可一键把该 provider 设为当前活跃（keyless 的 mock/ollama/zai 无需 key）。</li><li><strong>防窥掩码</strong>：key 输入框默认 <code>password</code> 型，&quot;show&quot; 显形 8 秒后自动重新掩码；已保存的 key 只以服务端掩码（<code>sk-***last4</code>）回显——明文只存在于本机请求体与 0600 配置文件，从不回显、从不进日志。gate/风险策略等安全相关配置仍然<strong>不可</strong>从浏览器修改。</li></ul>',22)])])}const g=o(r,[["render",i]]);export{u as __pageData,g as default};
